/*
 * A042678  Numerators of continued fraction convergents to sqrt(869).
 * https://oeis.org/A042678
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 9, u32 n <= 17, u64 n <= 37, u128 n <= 73,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A042678 – numerators of convergents to sqrt(869)
 *  The numerators p_k are generated by the standard recurrence
 *  for simple continued fractions of √869:
 *
 *        p_{-2} = 0,  p_{-1} = 1
 *        q_{-2} = 1,  q_{-1} = 0
 *        p_k   = a_k · p_{k-1} + p_{k-2}
 *        q_k   = a_k · q_{k-1} + q_{k-2}
 *
 *  where a_k are the partial quotients of √869,
 *  produced by the classic (m, d, a) scheme.
 *
 *  a_0 = ⌊√869⌋ = 29.
 *  For k ≥ 0:
 *      m_{k+1} = d_k · a_k – m_k
 *      d_{k+1} = (869 – m_{k+1}²) / d_k
 *      a_{k+1} = ⌊(a_0 + m_{k+1}) / d_{k+1}⌋
 *
 *  The function returns p_n for the requested index n (offset 0).
 *
 *  The implementation uses only integer arithmetic available for seq_t,
 *  so it works for 8/16/32/64‑bit unsigned types as well as arbitrary precision types.
 */
#include <stdint.h>

#define D 869ULL          /* D = 869 */
#define A0 29U            /* a_0 = floor(sqrt(869)) */

seq_t a(idx_t n)
{
    /* intermediate variables that stay comfortably in 64‑bit range */
    idx_t m = 0;          /* m_0 */
    idx_t d = 1;          /* d_0 */
    idx_t a_k = A0;       /* a_0 */

    /* p_{-2} and p_{-1} for the recurrence */
    seq_t p_prev2 = (seq_t)0;   /* p_{-2} */
    seq_t p_prev1 = (seq_t)1;   /* p_{-1} */

    for (idx_t i = 0; i <= n; ++i) {
        /* compute current numerator p_i */
        seq_t p_i = (seq_t)a_k * p_prev1 + p_prev2;

        /* if the desired index is reached, return the result */
        if (i == n) {
            return p_i;
        }

        /* update recurrence helpers for next iteration */
        idx_t m_next = d * a_k - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (A0 + m_next) / d_next;

        /* prepare for next k */
        m = m_next;
        d = d_next;
        a_k = a_next;

        /* shift numerator history */
        p_prev2 = p_prev1;
        p_prev1 = p_i;
    }

    /* unreachable but satisfy compiler */
    return (seq_t)0;
}
